  "ld": "{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"WebApplication\",\"@id\":\"https://markdown.digitum.marketing/google-docs-to-markdown#app\",\"name\":\"Digitum Google Docs to Markdown\",\"url\":\"https://markdown.digitum.marketing/google-docs-to-markdown\",\"description\":\"Convert Google Docs to Markdown from a link. Headings, bold, italic, lists, tables and links are kept. Works with any doc shared as anyone with the link.\",\"applicationCategory\":\"DeveloperApplication\",\"operatingSystem\":\"Any (web browser)\",\"browserRequirements\":\"Requires JavaScript. Works in Chrome, Edge, Firefox and Safari.\",\"offers\":{\"@type\":\"Offer\",\"price\":\"0\",\"priceCurrency\":\"USD\"},\"image\":\"https://markdown.digitum.marketing/og-image.png\",\"publisher\":{\"@id\":\"https://digitum.marketing/#org\"},\"inLanguage\":\"en\"},{\"@type\":\"Organization\",\"@id\":\"https://digitum.marketing/#org\",\"name\":\"Digitum Marketing\",\"url\":\"https://digitum.marketing/\",\"logo\":\"https://markdown.digitum.marketing/brand/logo-charcoal.png\"},{\"@type\":\"BreadcrumbList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Home\",\"item\":\"https://markdown.digitum.marketing/\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"All tools\",\"item\":\"https://markdown.digitum.marketing/tools\"},{\"@type\":\"ListItem\",\"position\":3,\"name\":\"Google Docs to Markdown\",\"item\":\"https://markdown.digitum.marketing/google-docs-to-markdown\"}]},{\"@type\":\"FAQPage\",\"@id\":\"https://markdown.digitum.marketing/google-docs-to-markdown#faq\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Does it work with private documents?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"No. For a private doc, copy its text and use Paste to Markdown.\"}},{\"@type\":\"Question\",\"name\":\"Are images kept?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Images are linked from Google's servers; download them if you need permanent copies.\"}},{\"@type\":\"Question\",\"name\":\"Can I go the other way?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes, with Markdown to Google Docs.\"}}]},{\"@type\":\"HowTo\",\"@id\":\"https://markdown.digitum.marketing/google-docs-to-markdown#howto\",\"name\":\"How to convert Google Docs to Markdown\",\"step\":[{\"@type\":\"HowToStep\",\"position\":1,\"text\":\"In Google Docs, set Share › General access to Anyone with the link.\"},{\"@type\":\"HowToStep\",\"position\":2,\"text\":\"Paste the link here and press Convert.\"},{\"@type\":\"HowToStep\",\"position\":3,\"text\":\"Copy or download the markdown.\"}]}]}",
